text(await tools.exec_command({cmd:"mkdir -p .evidence/u20/tmp docs/verification/u20 && python3 - <<'PY'
import hashlib,json,pathlib,subprocess,datetime
root=pathlib.Path.cwd(); out=root/'.evidence/u20'
paths=subprocess.check_output(['git','ls-files','-z']).decode().split('\0')
entries={p:'sha256:'+hashlib.sha256((root/p).read_bytes()).hexdigest() for p in paths if p and (root/p).is_file()}
record={'recorded_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'commit':subprocess.check_output(['git','rev-parse','HEAD']).decode().strip(),'git_status':subprocess.check_output(['git','status','--porcelain']).decode(),'files':entries}
(out/'basis.json').write_text(json.dumps(record,indent=2)+'\n')
print(json.dumps({k:v for k,v in record.items() if k!='files'})); print('fingerprinted_files',len(entries))
PY
PYTHONDONTWRITEBYTECODE=1 TMPDIR=/home/mike/regulatory-compliance/.evidence/u20/tmp /tmp/rci-u03-clean/bin/python -m pytest -q --basetemp=.evidence/u20/suite --junitxml=.evidence/u20/suite.xml -k 'not test_local_http_server and not test_manifest_exact_routes_and and not test_require_registers_cli' > .evidence/u20/suite.log 2>&1","yield_time_ms":1000,"max_output_tokens":1500}));
