p=pathlib.Path('config/review.u20.json')
c=json.loads(pathlib.Path('config/review.example.json').read_text());c['host']['owner']='Mike — attended U20 verification';p.write_text(json.dumps(c,indent=2)+'\n')
PY
PYTHONDONTWRITEBYTECODE=1 TMPDIR=/home/mike/regulatory-compliance/.evidence/u20/tmp /tmp/rci-u03-clean/bin/python regulatory-change-impact-brief/scripts/run.py --config config/review.u20.json > .evidence/u20/live-01.log 2>&1","yield_time_ms":1000,"max_output_tokens":1000}));
text(await tools.exec_command({cmd:"PYTHONDONTWRITEBYTECODE=1 TMPDIR=/home/mike/regulatory-compliance/.evidence/u20/tmp bash /home/mike/.codex/plugins/cache/fellowship-apprentice-workspace/apprentice-workspace/local/library/skills/scan-agent-skill/scripts/scan.sh regulatory-change-impact-brief > .evidence/u20/skill-scan.md 2>&1","yield_time_ms":1000,"max_output_tokens":1000}));
text(await tools.exec_command({cmd:"PYTHONDONTWRITEBYTECODE=1 /tmp/rci-u03-clean/bin/python -m pytest -q tests/runtime/test_u05.py -k 'test_local_http_server or test_manifest_exact_routes_and or test_require_registers_cli' --basetemp=/tmp/rci-u20-external --junitxml=.evidence/u20/external.xml > .evidence/u20/external.log 2>&1","yield_time_ms":1000,"max_output_tokens":1000}));

text(await tools.exec_command({cmd:"cat .evidence/u20/external.log && tail -8 .evidence/u20/live-01.log && cat .evidence/u20/skill-scan.md | head -65 && sed -n '1,240p' tests/runtime/test_u17_complete.py && cat docs/verification/check-u01.py","max_output_tokens":8000}));
